INSERT INTO factchecks (id, claim, truth, sources, created_at) VALUES (1, 'В социальных сетях массово распространяется видео, на котором якобы запечатлены недавние события в городе N.', 'На самом деле это видео было снято в 2018 году в совершенно другом регионе. Анализ метаданных и обратный поиск по изображениям это подтверждают.', '{"https://example.com/original-video-2018","Анализ независимых экспертов Bellingcat"}', '2026-04-03T15:49:50.131Z');
INSERT INTO factchecks (id, claim, truth, sources, created_at) VALUES (2, 'Появилась информация о закрытии всех выездов из города.', 'Официальные источники и очевидцы на местах подтверждают, что трассы М-4 и А-105 открыты для движения гражданского транспорта.', '{"Трансляции с дорожных камер","Свидетельства волонтеров на местах"}', '2026-04-03T15:49:50.131Z');
INSERT INTO factchecks (id, claim, truth, sources, created_at) VALUES (3, 'В сети распространяется видео с колонной техники в городе N.', 'Это классический пример панического вброса. Голос на аудио не идентифицирован, местные жители подтверждают штатную работу транспорта.', '{"https://example.com/source1","Независимый анализ"}', '2025-12-09T04:24:22.743Z');
