INSERT INTO factchecks (id, claim, truth, sources, created_at) VALUES (96, 'Появилась фотография якобы официального приказа о массовых проверках телефонов на улицах.', 'Это классический пример панического вброса. Голос на аудио не идентифицирован, местные жители подтверждают штатную работу транспорта.', '{"https://example.com/source1","Независимый анализ"}', '2025-10-17T07:52:59.835Z');
