INSERT INTO timeline_events (id, date_str, title, description, event_date, created_at) VALUES (1, 'Апрель 2026', 'Запуск платформы', 'Команда хакатона представила первую версию антивоенного сайта для агрегации проверенной информации.', '2026-04-02T19:00:00.000Z', '2026-04-03T15:49:50.131Z');
INSERT INTO timeline_events (id, date_str, title, description, event_date, created_at) VALUES (2, 'Март 2026', 'Подготовка к проекту', 'Сбор данных, интервью с экспертами по цифровой безопасности и планирование архитектуры.', '2026-03-14T19:00:00.000Z', '2026-04-03T15:49:50.131Z');
INSERT INTO timeline_events (id, date_str, title, description, event_date, created_at) VALUES (3, 'Февраль 2026', 'Идея создания', 'Возникла необходимость в единой платформе для фактчекинга на фоне роста дезинформации.', '2026-02-09T19:00:00.000Z', '2026-04-03T15:49:50.131Z');
